import { Box, Container, Stack, Typography } from "@mui/material";
import BlocksText from "../components/BlocksText";
import { mediaUrl } from "../services/api";
import type { HomeExplore } from "../types/home";

const NAVY = "#17224d";

export default function ExploreDevices({ data }: { data?: HomeExplore | null }) {
  if (!data) return null;

  return (
    <Box sx={{ py: { xs: 6, md: 9 }, backgroundColor: "#fff" }}>
      <Container maxWidth="lg">
        <Stack
          direction={{ xs: "column", md: "row" }}
          alignItems="center"
          justifyContent="space-between"
          spacing={{ xs: 4, md: 6 }}
        >
          <Box sx={{ flex: 1, maxWidth: { md: 520 } }}>
            <Typography
              sx={{
                color: NAVY,
                fontSize: { xs: 24, md: 32 },
                fontWeight: 700,
                lineHeight: 1.2,
                mb: 2,
              }}
            >
              {data.title}
            </Typography>
            <BlocksText
              content={data.description}
              sx={{
                color: "#5a6473",
                fontSize: { xs: 15, md: 18 },
                lineHeight: 1.65,
                "& strong": { fontWeight: 700, color: "#5a6473" },
                "& p": { mb: 0 },
              }}
            />
          </Box>
          {mediaUrl(data.image) ? (
            <Box sx={{ flex: 1, width: "100%", textAlign: "center" }}>
              <Box
                component="img"
                src={mediaUrl(data.image)}
                alt={data.image?.alternativeText || data.title || "Explore"}
                sx={{ width: "100%", maxWidth: 560, display: "block", mx: "auto" }}
              />
            </Box>
          ) : null}
        </Stack>
      </Container>
    </Box>
  );
}
